const alert = $json.body || $json;
const rule = alert.rule || {};
const agent = alert.agent || {};
const artifacts = alert.artifacts || {};

const agentIp = agent.ip && agent.ip !== 'N/A' ? agent.ip : '192.168.71.129';
const agentName = agent.name && agent.name !== 'Unknown' ? agent.name : 'DESKTOP-A2AG7TR';

// Raw network source IP if present
let rawSrcIp = artifacts.raw_src_ip || artifacts.src_ip;
if (!rawSrcIp || rawSrcIp === 'N/A' || rawSrcIp === '-' || rawSrcIp === '127.0.0.1' || rawSrcIp === '::1') {
  rawSrcIp = null;
}

// Determine target IOC and type
const iocType = artifacts.ioc_type || (rawSrcIp ? 'Network-Attacker' : 'Compromised-Endpoint');
const targetIoc = rawSrcIp || agentIp;
const displayIoc = rawSrcIp ? rawSrcIp : `${agentIp} (${agentName})`;

const isPrivate = /^(10\.|192\.168\.|172\.(1[6-9]|2[0-9]|3[0-1])\.|127\.)/.test(targetIoc);

return {
  alert_id: alert.alert_id || 'ALT-' + Date.now(),
  timestamp: alert.timestamp || new Date().toISOString(),
  rule_id: rule.id || 'N/A',
  rule_level: rule.level || 0,
  rule_desc: rule.description || 'Unknown Alert',
  mitre_ids: (rule.mitre_ids || []).join(', ') || 'N/A',
  agent_name: agentName,
  agent_ip: agentIp,
  src_ip: targetIoc,
  raw_src_ip: rawSrcIp || 'Local / Host-Internal',
  ioc_type: iocType,
  display_ioc: displayIoc,
  is_private_ip: isPrivate,
  process_name: artifacts.process_name || 'N/A',
  target_user: artifacts.target_user || 'N/A',
  command_line: artifacts.command_line || 'N/A',
  target_object: artifacts.target_object || 'N/A'
};

const item = $('Normalize & Triage').item.json;
const abuse = $json.data || {};

const isDeception = ['100014', '100015', '100016'].includes(String(item.rule_id));

let message = '';
let inlineKeyboard = {};

if (isDeception) {
  const attackerIp = (item.raw_src_ip && item.raw_src_ip !== 'Local / Host-Internal') ? item.raw_src_ip : (item.src_ip || '192.168.71.130');
  message = `🚨 <b>DECEPTION TRIPWIRE TRIGGERED</b>\n` +
    `━━━━━━━━━━━━━━━━━━━━━━\n` +
    `📌 <b>Rule:</b> [${item.rule_id}] ${item.rule_desc}\n` +
    `🎯 <b>MITRE ATT&CK:</b> <code>${item.mitre_ids}</code>\n` +
    `🌐 <b>Attacker IP:</b> <code>${attackerIp}</code>\n` +
    `💻 <b>Target Endpoint:</b> <code>${item.agent_ip} (${item.agent_name})</code>\n` +
    `👤 <b>Target User:</b> <code>${item.target_user}</code>\n` +
    `📦 <b>Evidence Archive:</b> <code>C:\\Windows\\Temp\\Forensics\\Evidence_*.zip</code>\n` +
    `🕒 <b>Time:</b> <code>${item.timestamp}</code>\n` +
    `━━━━━━━━━━━━━━━━━━━━━━\n` +
    `<i>Select active defense response action below (Human-in-the-Loop):</i>`;

  inlineKeyboard = {
    inline_keyboard: [
      [
        { text: '🛑 [Block Attacker IP]', callback_data: `action:block:${attackerIp}:${item.alert_id}` },
        { text: '🟢 [Unblock IP (Rollback)]', callback_data: `action:unblock:${attackerIp}:${item.alert_id}` }
      ],
      [
        { text: '📋 [Create Jira Ticket]', callback_data: `action:jira:${item.rule_id}:${attackerIp}:${item.alert_id}` },
        { text: '⚠️ [False Positive]', callback_data: `action:ignore:${attackerIp}:${item.alert_id}` }
      ]
    ]
  };
} else {
  const abuseScore = abuse.abuseConfidenceScore !== undefined ? abuse.abuseConfidenceScore : 'N/A (Local / Internal IP)';
  const totalReports = abuse.totalReports !== undefined ? abuse.totalReports : 0;
  const country = abuse.countryCode || 'Local Lab Network';

  const severityIcon = item.rule_level >= 12 ? '🚨 CRITICAL' : (item.rule_level >= 8 ? '⚠️ HIGH' : 'ℹ️ MEDIUM');

  let originLine = '';
  const isRemoteAttack = item.raw_src_ip && item.raw_src_ip !== 'Local / Host-Internal';

  if (isRemoteAttack) {
    originLine = `🌐 <b>Attacker IP:</b> <code>${item.raw_src_ip}</code> (${country})\n` +
                 `🔍 <b>AbuseIPDB Reputation:</b> <code>${abuseScore}%</code> (${totalReports} reports)\n`;
  } else {
    originLine = `🖥️ <b>Scope / Origin:</b> <code>Host-Internal Execution</code>\n` +
                 `⚙️ <b>Suspicious Process:</b> <code>${item.process_name || 'N/A'}</code>\n`;
  }

  message = `<b>${severityIcon} - WAZUH SOAR ALERT DISPATCH</b>\n` +
    `━━━━━━━━━━━━━━━━━━━━━━\n` +
    `📌 <b>Rule:</b> [${item.rule_id}] ${item.rule_desc}\n` +
    `🎯 <b>MITRE ATT&CK:</b> <code>${item.mitre_ids}</code>\n` +
    `🎯 <b>Target IOC / Endpoint:</b> <code>${item.display_ioc}</code>\n` +
    `👤 <b>Target User:</b> <code>${item.target_user}</code>\n` +
    originLine +
    `🕒 <b>Time:</b> <code>${item.timestamp}</code>\n` +
    `━━━━━━━━━━━━━━━━━━━━━━\n` +
    `<i>Select incident response action below (Human-in-the-Loop):</i>`;

  const isKillChainInternal = !isRemoteAttack || ['100004', '100005', '100006', '100007'].includes(String(item.rule_id));
  const isPersistence = ['100006', '100007'].includes(String(item.rule_id)) || (item.rule_desc && item.rule_desc.toLowerCase().includes('persistence'));

  if (isKillChainInternal) {
    const proc = item.process_name && item.process_name !== 'N/A' ? item.process_name : 'powershell.exe';
    const cleanProc = proc.split('\\').pop();
    const rows = [
      [
        { text: '🛑 [Kill Process]', callback_data: `action:killproc:${cleanProc}:${item.alert_id}` },
        { text: '🔒 [Isolate Host]', callback_data: `action:block:${item.agent_ip}:${item.alert_id}` }
      ]
    ];
    if (isPersistence) {
      rows.push([
        { text: '🧹 [Clean Persistence]', callback_data: `action:cleanpersist:${item.agent_ip}:${item.alert_id}` },
        { text: '📋 [Create Jira Ticket]', callback_data: `action:jira:${item.rule_id}:${item.agent_ip}:${item.alert_id}` }
      ]);
      rows.push([
        { text: '⚠️ [False Positive]', callback_data: `action:ignore:${item.agent_ip}:${item.alert_id}` }
      ]);
    } else {
      rows.push([
        { text: '📋 [Create Jira Ticket]', callback_data: `action:jira:${item.rule_id}:${item.agent_ip}:${item.alert_id}` },
        { text: '⚠️ [False Positive]', callback_data: `action:ignore:${item.agent_ip}:${item.alert_id}` }
      ]);
    }
    inlineKeyboard = { inline_keyboard: rows };
  } else {
    inlineKeyboard = {
      inline_keyboard: [
        [
          { text: '🚫 [Block IP 24h]', callback_data: `action:block:${item.src_ip}:${item.alert_id}` },
          { text: '⚠️ [False Positive]', callback_data: `action:ignore:${item.src_ip}:${item.alert_id}` }
        ],
        [
          { text: '📋 [Create Jira Ticket]', callback_data: `action:jira:${item.rule_id}:${item.src_ip}:${item.alert_id}` }
        ]
      ]
    };
  }
}

return {
  chat_id: '8696241190',
  text: message,
  reply_markup: inlineKeyboard,
  parse_mode: 'HTML'
};
